import{_ as n,l as i,o as a,c as l,v as r,p as s,x as o,d as p,i as h,S as c}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"Debreu 价值理论","description":"","frontmatter":{"title":"Debreu 价值理论","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/debreu-theory-of-value.md","filePath":"econ/debreu-theory-of-value.md","lastUpdated":1789023840000}'),d={name:"econ/debreu-theory-of-value.md"};function u(E,e,A,f,m,b){const t=i("Mermaid");return a(),l("div",null,[e[1]||(e[1]=r('<h1 id="debreu-价值理论" tabindex="-1">Debreu 价值理论 <a class="header-anchor" href="#debreu-价值理论" aria-label="Permalink to &quot;Debreu 价值理论&quot;">​</a></h1><div class="epigraph"><p>本书的目的，是对竞争经济均衡做一次公理化分析。</p><footer>—— Debreu, Theory of Value: An Axiomatic Analysis of Economic Equilibrium, Cowles Monograph 17, 1959</footer></div><p><a href="/econ/arrow-debreu-paper">上一课</a>（Arrow–Debreu 或有商品）。附录对照。<a href="/econ/arrow-debreu-paper">上一篇</a>钉的是 Arrow 证券对或有商品的降维。本篇对照 <strong>Debreu 1959 原书</strong>：把商品空间、偏好、生产、均衡与福利收成一套可引用的公理，而不是课堂版的盒与超平面口诀。主干<a href="/econ/welfare-theorems">福利两定理</a>与<a href="/econ/ge-existence">存在性</a>已经取用结论；这里看原书怎样把日期、地点、状态写进同一商品向量。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>1954 年论文证明存在，但商品仍是抽象的 \\(\\mathbb{R}^L\\)。缺口是统一语言：同一套符号要同时覆盖跨期、空间与不确定，而不另起「宏观」或「金融」章节。Debreu 的解决是把商品定义为物理性质、地点、日期与事件的组合。价格是该空间上的线性函数。一旦接受这一定义，不确定与时间不再是新理论，只是 \\(L\\) 变大。</p><p>原书明确走布尔巴基式的公理路线：先列消费集、偏好的连续性与凸性、生产集的闭凸与不可逆，再陈述均衡与帕累托，最后用角谷。它不是经济史，也不给算法。</p><p><span class="marginnote">Cowles 专著 17。九章从商品与价格写到不确定。存在性用角谷，不用布劳威尔对付对应。私有制经济（private ownership）把利润按股份分配，均衡定义里利润必须被分完。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>商品空间是有限维欧氏空间。消费集闭、凸、下有界；偏好用完备、传递、连续、凸的预序（不必先写效用函数；效用是表示，不是原语——对照主干<a href="/econ/utility-representation">效用表示</a>）。生产集含 \\(0\\)、闭凸、不能免费生产。均衡是价格、消费与生产计划，使需求在预算上最优、生产利润最大、市场出清。福利两定理在局部非饱和与凸性下陈述；第二定理用分离超平面，转移是总额的。</p><p>不确定一章把事件树写进商品下标，正是上一篇 Arrow 证券的商品侧。书中不讨论证券的动态交易策略，也不讨论不完全市场。</p>',10)),(a(),s(c,null,{default:o(()=>[h(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20COMM%5B%22%E5%95%86%E5%93%81%3A%20%E6%80%A7%E8%B4%A8%20x%20%E5%9C%B0%20x%20%E6%97%B6%20x%20%E4%BA%8B%E4%BB%B6%22%5D%20--%3E%20PREF%5B%22%E8%BF%9E%E7%BB%AD%E5%87%B8%E9%A2%84%E5%BA%8F%22%5D%0A%20%20PREF%20--%3E%20EQ%5B%22%E7%A7%81%E6%9C%89%E5%88%B6%E5%9D%87%E8%A1%A1%22%5D%0A%20%20PROD%5B%22%E9%97%AD%E5%87%B8%E7%94%9F%E4%BA%A7%E9%9B%86%22%5D%20--%3E%20EQ%0A%20%20EQ%20--%3E%20FWT%5B%22%E4%B8%A4%E5%AE%9A%E7%90%86%20%2B%20%E8%A7%92%E8%B0%B7%E5%AD%98%E5%9C%A8%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是线性价格在凸性上的支撑。凸偏好使「更好的集合」可被超平面分开，价格于是既是出清信号又是福利支撑。公理化的代价是：凡凸性失败（不可分、规模报酬递增），存在与第二定理一起停。原书把失败留在假设里，不提供非凸存在的一般定理。</p><p>与 Arrow 1953/1964 的分工：Debreu 把状态写进商品；Arrow 说明可用证券结算购买力。两篇对照才构成「或有商品经济」的课堂缩写。主干若只引 1954 存在性，会漏掉商品定义本身。</p><h3 id="效用是表示-不是原始对象" tabindex="-1">效用是表示，不是原始对象 <a class="header-anchor" href="#效用是表示-不是原始对象" aria-label="Permalink to &quot;效用是表示，不是原始对象&quot;">​</a></h3><p>书的章节顺序禁止先写 \\(\\max u(x)\\)：先有商品空间上的偏好公理，连续效用是定理。主干第一课<a href="/econ/preference-choice">偏好</a>的禁令出自这里。货币在书中没有特殊地位；<a href="/econ/money-as-medium">货币层次</a>必须另找摩擦。柠檬、信号、银行全部在公理之外。读附录是为了看见主干从哪一组假设出发，不是把 1959 年专论插入微观课序中间。</p><p><span class="marginnote">Cowles Foundation Monograph 17, Wiley / Yale, 1959。与 1954 年 Econometrica 短文不是同一文献。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>原书有限维、有限代理人、完全市场。无限维商品（连续时间消费）、测度空间上的代理人、太阳黑子，都是后继文献。不要把《价值理论》读成已经包含 <a href="/econ/capm-theory">CAPM</a> 或 <a href="/econ/stochastic-discount-factor">SDF</a>——那些要再加偏好与证券结构。也不要在附录复述盒的图画：那是主干埃奇沃思课的教具。</p><p>下一篇附录离开完全信息的竞争，对照 Akerlof 1970 的柠檬市场原文。</p><p>Mas-Colell, Whinston and Green 是教学展开；Debreu 是公理核。不要在附录复述斯勒茨基或厂商供给——那些是主干已经写过的推导。</p><p>效用是表示定理，不是第 1 章的原始对象。主干偏好课禁止先写 \\(\\max u(x)\\)，出处在这本书。</p><p>货币、银行、柠檬不在书中。那些课程必须另加摩擦，不是 Debreu 的未完成章节。</p><p>有限维、有限代理人、完全市场是主场域。无限维与测度空间上的代理人是后继。</p><p>1954 年论文与 1959 年书不要混引成同一文献：一篇存在性短文，一本公理专论。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>附录对照 Debreu 1959：竞争均衡的公理化，商品含时、地、状态。</li><li>存在与两定理是书中定理，不是口诀；凸性是支撑价格的关键。</li><li>与 Arrow 证券文分工：商品定义 vs 证券实施。</li><li>出处：Debreu, <em>Theory of Value</em>, 1959。</li></ul>',16))])}const D=n(d,[["render",u]]);export{B as __pageData,D as default};
